parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "hairstyle": {
      "type": "string",
      "description": "The specific hairstyle the customer has decided on (e.g. Fade, Undercut, Buzz Cut, Pompadour, Crew Cut, Long Layers), or empty string if not decided yet"
    },
    "stylist": {
      "type": "string",
      "description": "The roster stylist matched to the chosen hairstyle. Must be one of the roster stylists. Empty string until a stylist has been matched and the customer has confirmed."
    },
    "reply": {
      "type": "string",
      "description": "The natural-language message to show the customer (advice, suggestions, questions, or confirmation of the hairstyle and matched stylist)"
    }
  },
  "required": [
    "hairstyle",
    "stylist",
    "reply"
  ]
}

parameters.jsCode:
const rows = $input.all().map(i => i.json).filter(r => r.active === true || r.active === 'true');
const roster = rows.length
  ? rows.map(r => `- ${r.name} — specialises in ${r.specialty} (${r.styles}).`).join('\n')
  : 'No stylists are currently available.';
return [{ json: { roster } }];
